#include "KS/SRC/ks/igo_widget_shared.h"
#include "KS/SRC/ks/FEPanel_shared.h"

class SpecialMeter;

class SplitScoreWidget : public IGOWidget {
    SpecialMeter *meter;
    PanelQuad *bgPQ;
    TextString *scoreText;

public:
    virtual ~SplitScoreWidget();
    virtual void SetDisplay(bool enabled = true);
    virtual void Update(float time_inc);
    virtual void Draw();
    virtual bool GetDisplay() const;
    virtual void Init(PanelFile &panel, Font *font, bool left);
    virtual void SetScore(int score);
};

__asm__(".equ GetPointer__9PanelFilePCc, 0x00152F88");

void SplitScoreWidget::Init(PanelFile & panel, Font * font, const bool left)
{
    scoreText->setFont(font);

    if (left)
    {
        bgPQ = panel.GetPointer("left_counter");
        scoreText->changePos(213, 66);
    }
    else
    {
        bgPQ = panel.GetPointer("right_counter");
        scoreText->changePos(529, 66);
    }
    bgPQ->TurnOn(true);

    SetScore(0);

    SetDisplay(true);
}
